// ═══ THE RULE ═══
int threshold = 50000;  // effectively final — never reassigned
trades.stream().filter(t -> t.getAmount() > threshold);  // (Recommended) captures copy of 50000

// int threshold = 50000;
// threshold = 100000;  // ← REASSIGNMENT breaks effectively-final!
// trades.stream().filter(t -> t.getAmount() > threshold);  // (Avoid) COMPILE ERROR

// ═══ WORKAROUND 1: AtomicInteger (RECOMMENDED) ═══
AtomicInteger counter = new AtomicInteger(0);  // reference is final
    trades.stream().filter(t -> { counter.incrementAndGet();
    return t.isSettled(); });
// counter reference never changes — value inside changes via CAS (thread-safe)

// ═══ WORKAROUND 2: final int[] (NOT thread-safe) ═══
final int[] count = {0};  // array reference is final
    trades.stream().filter(t -> { count[0]++;
    return t.isSettled(); });
// (Caution) NOT safe for parallelStream — race condition on count[0]++!
