package com.bank.java8;

import org.junit.jupiter.api.Test;
import java.util.List;
import java.util.concurrent.atomic.AtomicInteger;
import static org.assertj.core.api.Assertions.assertThat;

class EffectivelyFinalTest {

    @Test
    void captureNeedsEffectivelyFinalOrWorkaround() {
        List<Integer> fees = List.of(10, 20, 30);
        int threshold = 15;                 // effectively final → can be captured

        long count = fees.stream().filter(f -> f > threshold).count();
        assertThat(count).isEqualTo(2);

        AtomicInteger total = new AtomicInteger();   // workaround for mutable capture
        fees.forEach(total::addAndGet);
        assertThat(total.get()).isEqualTo(60);
    }
}
